package main

import (
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path"
	"path/filepath"
	"strings"
	"sync"
)

type Role string

const (
	RoleAdmin  Role = "admin"
	RoleEditor Role = "editor"
	RoleViewer Role = "viewer"
)

type User struct {
	Username string `json:"username"`
	Role     Role   `json:"role"`
	Token    string `json:"token"`
}

type IndexEntry struct {
	DocID    string   `json:"doc_id"`
	Path     string   `json:"path"`
	Keywords []string `json:"keywords"`
}

type SearchService struct {
	mu       sync.RWMutex
	indexDir string
	users    map[string]*User
}

var service *SearchService

func NewSearchService(indexDir string) *SearchService {
	os.MkdirAll(indexDir, 0750)
	return &SearchService{
		indexDir: indexDir,
		users: map[string]*User{
			"admin-token-xyz": {Username: "admin", Role: RoleAdmin, Token: "admin-token-xyz"},
			"editor-token-abc": {Username: "editor", Role: RoleEditor, Token: "editor-token-abc"},
			"viewer-token-def": {Username: "viewer", Role: RoleViewer, Token: "viewer-token-def"},
		},
	}
}

func (s *SearchService) authenticate(r *http.Request) (*User, error) {
	token := r.Header.Get("X-Auth-Token")
	if token == "" {
		return nil, fmt.Errorf("missing authentication token")
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	for _, u := range s.users {
		if subtle.ConstantTimeCompare([]byte(u.Token), []byte(token)) == 1 {
			return u, nil
		}
	}
	return nil, fmt.Errorf("invalid token")
}

func (s *SearchService) authorize(user *User, requiredRole Role) bool {
	roleHierarchy := map[Role]int{RoleViewer: 1, RoleEditor: 2, RoleAdmin: 3}
	return roleHierarchy[user.Role] >= roleHierarchy[requiredRole]
}

// sanitizeCollectionName ensures the collection name is safe for filesystem use
func sanitizeCollectionName(name string) string {
	// Remove any path separators and null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	// Use path.Clean to normalize
	name = path.Clean(name)
	// Extract just the base name to prevent directory traversal
	name = filepath.Base(name)
	return name
}

// resolveIndexPath builds the full path for an index file within a collection
func (s *SearchService) resolveIndexPath(collection, docID string) (string, error) {
	safeCollection := sanitizeCollectionName(collection)
	if safeCollection == "." || safeCollection == "" {
		return "", fmt.Errorf("invalid collection name")
	}

	// Sanitize docID: allow alphanumeric, hyphens, underscores, and dots
	for _, c := range docID {
		if !isAllowedDocIDChar(c) {
			return "", fmt.Errorf("invalid character in document ID: %c", c)
		}
	}

	// Build path using filepath.Join for OS-appropriate separators
	fullPath := filepath.Join(s.indexDir, safeCollection, docID+".json")

	// Verify the resolved path is within the index directory
	absPath, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}
	absBase, err := filepath.Abs(s.indexDir)
	if err != nil {
		return "", err
	}

	// Security check: ensure path stays within index directory
	if !strings.HasPrefix(absPath, absBase) {
		return "", fmt.Errorf("path traversal detected")
	}

	return fullPath, nil
}

func isAllowedDocIDChar(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
		(c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.'
}

func handleIndex(w http.ResponseWriter, r *http.Request) {
	user, err := service.authenticate(r)
	if err != nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if !service.authorize(user, RoleEditor) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	var entry IndexEntry
	if err := json.NewDecoder(r.Body).Decode(&entry); err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	collection := r.URL.Query().Get("collection")
	if collection == "" {
		collection = "default"
	}

	indexPath, err := service.resolveIndexPath(collection, entry.DocID)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	service.mu.Lock()
	defer service.mu.Unlock()

	os.MkdirAll(filepath.Dir(indexPath), 0750)

	data, err := json.Marshal(entry)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	if err := ioutil.WriteFile(indexPath, data, 0640); err != nil {
		http.Error(w, "Write failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]string{"status": "indexed", "path": indexPath})
}

func handleSearch(w http.ResponseWriter, r *http.Request) {
	user, err := service.authenticate(r)
	if err != nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if !service.authorize(user, RoleViewer) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	collection := r.URL.Query().Get("collection")
	if collection == "" {
		collection = "default"
	}

	safeCollection := sanitizeCollectionName(collection)
	collectionDir := filepath.Join(service.indexDir, safeCollection)

	files, err := ioutil.ReadDir(collectionDir)
	if err != nil {
		http.Error(w, "Collection not found", http.StatusNotFound)
		return
	}

	keyword := r.URL.Query().Get("q")
	var results []IndexEntry

	for _, f := range files {
		data, err := ioutil.ReadFile(filepath.Join(collectionDir, f.Name()))
		if err != nil {
			continue
		}
		var entry IndexEntry
		if err := json.Unmarshal(data, &entry); err != nil {
			continue
		}
		for _, kw := range entry.Keywords {
			if strings.Contains(strings.ToLower(kw), strings.ToLower(keyword)) {
				results = append(results, entry)
				break
			}
		}
	}

	json.NewEncoder(w).Encode(results)
}

func main() {
	service = NewSearchService("/var/data/search-index")
	http.HandleFunc("/index", handleIndex)
	http.HandleFunc("/search", handleSearch)
	fmt.Println("Search indexing service starting on :8080")
	http.ListenAndServe(":8080", nil)
}
